  list.forEach(function(n){if(skip(n.parentElement)||!n.nodeValue.trim())return;if(!orig.has(n))orig.set(n,n.nodeValue);n.nodeValue=T(orig.get(n));});
  root.querySelectorAll('[placeholder]').forEach(function(e){if(skip(e))return;if(e.dataset.ph===undefined)e.dataset.ph=e.placeholder;e.placeholder=T(e.dataset.ph);});
  root.querySelectorAll('[aria-label]').forEach(function(e){if(skip(e))return;if(e.dataset.al===undefined)e.dataset.al=e.getAttribute('aria-label');e.setAttribute('aria-label',T(e.dataset.al));});
